module.exports = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>QR Magic（個人用）</title>\n  <style>\n    :root {\n      color-scheme: dark;\n      font-family: Inter, \"SF Pro Display\", \"Hiragino Sans\", \"Yu Gothic UI\", system-ui, sans-serif;\n      color: #f6f0e8;\n      background: #101010;\n      --bg: #101010;\n      --panel: #181817;\n      --panel-2: #20201f;\n      --line: rgba(246, 240, 232, .12);\n      --line-strong: rgba(246, 240, 232, .22);\n      --text: #f6f0e8;\n      --muted: #a9a39a;\n      --soft: #d8d0c5;\n      --primary: #d7b56d;\n      --primary-ink: #17120b;\n      --accent: #54b7a1;\n      --danger: #db5c53;\n      --shadow: 0 18px 50px rgba(0,0,0,.34);\n    }\n    * { box-sizing: border-box; }\n    html { min-height: 100%; background: var(--bg); }\n    body {\n      margin: 0 auto;\n      width: min(100%, 560px);\n      min-height: 100vh;\n      padding: 1.15rem 1rem 3rem;\n      background:\n        linear-gradient(180deg, rgba(215,181,109,.09), rgba(16,16,16,0) 13rem),\n        var(--bg);\n    }\n    h1 { font-size: 1.5rem; line-height: 1.05; margin: 0; letter-spacing: 0; }\n    h2 { font-size: 0.78rem; margin: 0 0 0.7rem; color: var(--muted); letter-spacing: 0; font-weight: 700; text-transform: uppercase; }\n    h3 { font-size: 0.9rem; margin: 0; }\n    input[type=\"text\"], input[type=\"password\"], textarea, select {\n      width: 100%;\n      padding: 0.78rem 0.85rem;\n      font-size: 1rem;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #111;\n      color: var(--text);\n      outline: none;\n      box-shadow: inset 0 1px 0 rgba(255,255,255,.03);\n    }\n    input[type=\"text\"]:focus, input[type=\"password\"]:focus, textarea:focus, select:focus, input[type=\"number\"]:focus {\n      border-color: rgba(215,181,109,.72);\n      box-shadow: 0 0 0 3px rgba(215,181,109,.13), inset 0 1px 0 rgba(255,255,255,.03);\n    }\n    input[type=\"number\"] {\n      padding: 0.66rem 0.7rem;\n      font-size: 1rem;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #111;\n      color: var(--text);\n      outline: none;\n    }\n    textarea { min-height: 2.5rem; resize: vertical; }\n    button {\n      cursor: pointer;\n      border: 1px solid transparent;\n      border-radius: 8px;\n      padding: 0.72rem 1rem;\n      font-size: 0.95rem;\n      font-weight: 700;\n      letter-spacing: 0;\n      transition: transform .12s ease, border-color .12s ease, background .12s ease, opacity .12s ease;\n    }\n    button:hover { transform: translateY(-1px); }\n    button:active { transform: translateY(0); }\n    button:disabled { opacity: 0.52; cursor: not-allowed; }\n    .btn-primary { background: var(--primary); color: var(--primary-ink); border-color: rgba(255,255,255,.08); }\n    .btn-secondary { background: rgba(246,240,232,.08); color: var(--text); border-color: var(--line); }\n    .btn-danger { background: rgba(219,92,83,.18); color: #ffd9d5; border-color: rgba(219,92,83,.34); }\n    .panel {\n      background: linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.01)), var(--panel);\n      border-radius: 8px;\n      padding: 1rem;\n      border: 1px solid var(--line);\n      margin-top: 0.78rem;\n      box-shadow: 0 1px 0 rgba(255,255,255,.03);\n    }\n    .muted { color: var(--muted); font-size: 0.85rem; word-break: break-all; }\n    .toolbar { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.65rem; align-items: center; }\n    .brandHeader {\n      display: flex;\n      align-items: flex-end;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 0.6rem 0 0.7rem;\n    }\n    .brandMark {\n      display: inline-grid;\n      place-items: center;\n      width: 2.6rem;\n      height: 2.6rem;\n      border-radius: 8px;\n      background: #f6f0e8;\n      color: #111;\n      font-weight: 900;\n      margin-bottom: 0.6rem;\n      box-shadow: 0 8px 28px rgba(0,0,0,.34);\n    }\n    .brandKicker { color: var(--primary); font-size: 0.75rem; font-weight: 800; margin: 0 0 0.35rem; letter-spacing: 0; }\n    .versionPill {\n      flex: 0 0 auto;\n      border: 1px solid var(--line);\n      background: rgba(246,240,232,.06);\n      border-radius: 999px;\n      padding: 0.32rem 0.58rem;\n      font-size: 0.72rem;\n      color: var(--soft);\n      margin: 0 0 0.15rem;\n    }\n    .settingsFab {\n      position: fixed;\n      top: 0.75rem;\n      right: 0.75rem;\n      z-index: 80;\n      display: none;\n      align-items: center;\n      gap: 0.35rem;\n      padding: 0.5rem 0.78rem;\n      font-size: 0.88rem;\n      font-weight: 600;\n      border-radius: 999px;\n      background: rgba(24,24,23,.94);\n      border: 1px solid var(--line-strong);\n      box-shadow: var(--shadow);\n      color: var(--text);\n      backdrop-filter: blur(12px);\n    }\n    .settingsFab.settingsFab--visible { display: inline-flex; }\n    .settingsBackdrop {\n      display: none;\n      position: fixed;\n      inset: 0;\n      z-index: 90;\n      background: rgba(0,0,0,.56);\n      backdrop-filter: blur(2px);\n    }\n    .settingsBackdrop.settingsBackdrop--open { display: block; }\n    .settingsDrawer {\n      display: none;\n      position: fixed;\n      top: 0;\n      right: 0;\n      bottom: 0;\n      width: min(100vw, 25rem);\n      z-index: 100;\n      background: #141413;\n      border-left: 1px solid var(--line);\n      box-shadow: -18px 0 60px rgba(0,0,0,.42);\n      flex-direction: column;\n      overflow: hidden;\n    }\n    .settingsDrawer.settingsDrawer--open { display: flex; }\n    .settingsDrawerHead {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 0.5rem;\n      padding: 0.85rem 1rem;\n      border-bottom: 1px solid var(--line);\n      flex-shrink: 0;\n    }\n    .settingsDrawerHead h2 { font-size: 0.95rem; margin: 0; }\n    .settingsDrawerBody { padding: 0.75rem 0.85rem 1.25rem; overflow: auto; flex: 1; }\n    .settingsDrawerBody textarea { font-size: 0.72rem; font-family: ui-monospace, monospace; min-height: 9rem; }\n    .settingsSection { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); margin-bottom: 0.55rem; overflow: hidden; }\n    .settingsSection summary {\n      cursor: pointer;\n      list-style: none;\n      padding: 0.72rem 0.75rem;\n      font-weight: 700;\n      display: flex;\n      justify-content: space-between;\n      gap: 0.75rem;\n      align-items: center;\n    }\n    .settingsSection summary::-webkit-details-marker { display: none; }\n    .settingsSection summary::after { content: \"開く\"; color: var(--primary); font-size: 0.76rem; font-weight: 800; white-space: nowrap; }\n    .settingsSection[open] summary { border-bottom: 1px solid var(--line); background: rgba(246,240,232,.035); }\n    .settingsSection[open] summary::after { content: \"閉じる\"; }\n    .settingsSectionBody { padding: 0.75rem; }\n    .qrStateList { display: grid; gap: 0.4rem; max-height: 18rem; overflow: auto; margin-top: 0.55rem; }\n    .qrStateRow { border: 1px solid var(--line); border-radius: 8px; padding: 0.55rem; background: #111; }\n    .qrStateTop { display: flex; justify-content: space-between; gap: 0.5rem; align-items: center; }\n    .badge { display: inline-flex; align-items: center; border-radius: 999px; padding: 0.18rem 0.5rem; font-size: 0.72rem; font-weight: 800; background: rgba(246,240,232,.09); color: var(--soft); white-space: nowrap; }\n    .badge--fixed { background: rgba(84,183,161,.18); color: #91e6d3; }\n    .badge--hit { background: rgba(215,181,109,.18); color: #f2d68e; }\n    #app { display: grid; gap: 0; }\n    #keyword { font-size: 1.28rem; font-weight: 800; padding: 0.9rem 0.95rem; }\n    .injectUrlPanel { margin-top: 0.2rem; }\n    .copyRow { display: grid; grid-template-columns: 1fr auto; gap: 0.5rem; align-items: center; }\n    .copyRow input { font-size: 0.92rem; font-weight: 700; }\n    .copyRow button { padding: 0.72rem 0.82rem; white-space: nowrap; }\n    #toast {\n      border: 1px solid var(--line-strong);\n      box-shadow: var(--shadow);\n    }\n    @media (min-width: 720px) {\n      body { padding-top: 1.6rem; }\n    }\n  </style>\n</head>\n<body>\n  <button type=\"button\" class=\"settingsFab\" id=\"btnOpenSettings\" aria-haspopup=\"dialog\" aria-expanded=\"false\" aria-controls=\"settingsDrawer\">\n    設定\n  </button>\n  <div class=\"settingsBackdrop\" id=\"settingsBackdrop\" aria-hidden=\"true\"></div>\n  <div class=\"settingsDrawer\" id=\"settingsDrawer\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"settingsDrawerTitle\">\n    <div class=\"settingsDrawerHead\">\n      <h2 id=\"settingsDrawerTitle\">設定</h2>\n      <button type=\"button\" class=\"btn-secondary\" id=\"btnCloseSettings\" style=\"padding:0.4rem 0.65rem;font-size:0.82rem\">閉じる</button>\n    </div>\n    <div class=\"settingsDrawerBody\">\n      <details class=\"settingsSection\" id=\"settingsIssueSection\">\n        <summary>名刺用URLの発行</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"ticketStatus\" class=\"muted\" style=\"margin-top:0\"></p>\n          <label class=\"muted\">枚数</label>\n          <input type=\"number\" id=\"ticketCount\" value=\"10\" min=\"1\" max=\"5000\" style=\"width:6rem;margin-left:.35rem\" />\n          <div class=\"toolbar\">\n            <button type=\"button\" class=\"btn-primary\" id=\"btnIssueTickets\">発行</button>\n            <button type=\"button\" class=\"btn-danger\" id=\"btnClearTickets\">全削除</button>\n          </div>\n          <label class=\"muted\" style=\"display:block;margin-top:0.65rem\">発行されたURL</label>\n          <textarea id=\"ticketUrls\" readonly rows=\"8\"></textarea>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\" id=\"settingsUrlSection\">\n        <summary>有効URL一覧</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"settingsUrlMeta\" class=\"muted\" style=\"margin:0 0 0.5rem;font-size:0.8rem\"></p>\n          <div class=\"toolbar\" style=\"margin-top:0;margin-bottom:0.5rem\">\n            <button type=\"button\" class=\"btn-secondary\" id=\"btnRefreshUrlList\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">更新</button>\n          </div>\n          <textarea id=\"settingsUrlList\" readonly rows=\"8\"></textarea>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\" id=\"settingsQrStateSection\">\n        <summary>QRごとの状態</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"qrStateSummary\" class=\"muted\" style=\"margin-top:0\"></p>\n          <div class=\"toolbar\">\n            <button type=\"button\" class=\"btn-secondary\" id=\"btnRefreshQrState\">更新</button>\n          </div>\n          <div id=\"qrStateList\" class=\"qrStateList\"></div>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\" id=\"settingsHistorySection\">\n        <summary>アクセス履歴</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"settingsHistoryMeta\" class=\"muted\" style=\"margin:0 0 0.5rem;font-size:0.8rem\"></p>\n          <div class=\"toolbar\" style=\"margin-top:0;margin-bottom:0.5rem\">\n            <button type=\"button\" class=\"btn-secondary\" id=\"btnRefreshHistory\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">更新</button>\n          </div>\n          <label class=\"muted\" for=\"settingsHistoryList\" style=\"font-size:0.78rem\">URLごとの読取回数</label>\n          <textarea id=\"settingsHistoryList\" readonly rows=\"6\" style=\"margin-top:0.35rem\"></textarea>\n          <label class=\"muted\" for=\"settingsRecentEvents\" style=\"display:block;margin-top:.45rem;font-size:0.78rem\">直近の読取イベント</label>\n          <textarea id=\"settingsRecentEvents\" readonly rows=\"6\" style=\"margin-top:0.35rem\"></textarea>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\">\n        <summary>QR画像ZIP</summary>\n        <div class=\"settingsSectionBody\">\n          <p class=\"muted\" style=\"margin:0 0 0.5rem;font-size:0.8rem\">発行済み名刺URLをPNG化してZIPで保存します。</p>\n          <button type=\"button\" class=\"btn-primary\" id=\"btnDownloadQrZip\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">ZIPをダウンロード</button>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\">\n        <summary>ひとつ戻す</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"undoStateMeta\" class=\"muted\" style=\"margin-top:0\"></p>\n          <button type=\"button\" class=\"btn-secondary\" id=\"btnUndoState\">直前の設定に戻す</button>\n        </div>\n      </details>\n\n      <details class=\"settingsSection\" id=\"adminCodePanel\" style=\"display:none\">\n        <summary>ログインID管理</summary>\n        <div class=\"settingsSectionBody\">\n          <p id=\"adminCodeMeta\" class=\"muted\" style=\"margin:0 0 0.5rem;font-size:0.8rem\"></p>\n          <div class=\"toolbar\" style=\"margin-top:0;margin-bottom:0.5rem\">\n            <input type=\"number\" id=\"adminIssueCount\" value=\"50\" min=\"1\" max=\"5000\" style=\"width:7rem\" />\n            <button type=\"button\" class=\"btn-primary\" id=\"btnAdminIssueCodes\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">ID発行</button>\n            <button type=\"button\" class=\"btn-secondary\" id=\"btnAdminRefreshCodes\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">更新</button>\n          </div>\n          <textarea id=\"adminCodeList\" readonly rows=\"8\"></textarea>\n          <div class=\"toolbar\">\n            <input type=\"text\" id=\"adminRevokeCode\" placeholder=\"停止する8桁ID\" inputmode=\"numeric\" maxlength=\"8\" style=\"width:10rem\" />\n            <button type=\"button\" class=\"btn-danger\" id=\"btnAdminRevokeCode\" style=\"font-size:0.85rem;padding:0.45rem 0.75rem\">ID停止</button>\n          </div>\n        </div>\n      </details>\n    </div>\n  </div>\n\n  <header class=\"brandHeader\">\n    <div>\n      <div class=\"brandMark\">QR</div>\n      <p class=\"brandKicker\">PRIVATE REDIRECT CONSOLE</p>\n      <h1>QR Magic</h1>\n    </div>\n    <p id=\"appVersionBar\" class=\"versionPill\">バージョン …</p>\n  </header>\n\n  <div class=\"panel injectUrlPanel\">\n    <h2>インジェクトモードURL</h2>\n    <div class=\"copyRow\">\n      <input type=\"text\" id=\"injectModeUrl\" readonly value=\"https://qr-magic-tk7m.onrender.com/g\" aria-label=\"インジェクトモードURL\" />\n      <button type=\"button\" class=\"btn-secondary\" id=\"btnCopyInjectUrl\">コピー</button>\n    </div>\n  </div>\n\n  <div id=\"gate\" class=\"panel\">\n    <h2>ログインID</h2>\n    <p class=\"muted\">8桁の数字IDを入力してください。</p>\n    <input type=\"password\" id=\"gateToken\" placeholder=\"例: 12345678\" autocomplete=\"off\" />\n    <div class=\"toolbar\" style=\"margin-top:0.65rem\">\n      <button type=\"button\" class=\"btn-primary\" id=\"gateBtn\">開く</button>\n    </div>\n  </div>\n\n  <div id=\"app\" style=\"display:none\">\n    <div class=\"panel\">\n      <h2>テンプレート</h2>\n      <select id=\"templateSelect\" aria-label=\"テンプレート\" style=\"margin-top:0.35rem\"></select>\n    </div>\n\n    <div class=\"panel\">\n      <h2>モード選択</h2>\n      <div class=\"toolbar\">\n        <button type=\"button\" class=\"btn-secondary\" id=\"btnModeRecycle\">リサイクル</button>\n        <button type=\"button\" class=\"btn-secondary\" id=\"btnModeFrozen\">永久化</button>\n      </div>\n      <p id=\"modeLine\" class=\"muted\" style=\"margin:0.5rem 0 0\"></p>\n    </div>\n\n    <div class=\"panel\">\n      <h2>キーワード</h2>\n      <input type=\"text\" id=\"keyword\" placeholder=\"例: りんご\" autocomplete=\"off\" />\n      <div class=\"toolbar\">\n        <button type=\"button\" class=\"btn-primary\" id=\"saveBtn\">送信</button>\n        <button type=\"button\" class=\"btn-secondary\" id=\"btnPreviewKeyword\">プレビュー</button>\n      </div>\n    </div>\n  </div>\n\n  <p id=\"toast\" style=\"display:none;position:fixed;bottom:1rem;left:50%;transform:translateX(-50%);background:#181817;color:#f6f0e8;padding:.6rem 1rem;border-radius:8px;z-index:120\"></p>\n\n  <script>\n    const LS = \"qr_magic_session_token\";\n    const gate = document.getElementById(\"gate\");\n    const appEl = document.getElementById(\"app\");\n\n    let sessionToken = localStorage.getItem(LS) || \"\";\n    let actor = null;\n    let state = null;\n    let publicBaseUrl = \"\";\n    let qrStateRows = [];\n\n    function toast(msg) {\n      const t = document.getElementById(\"toast\");\n      t.textContent = msg;\n      t.style.display = \"block\";\n      setTimeout(() => { t.style.display = \"none\"; }, 2200);\n    }\n\n    function authHeaders() {\n      return { Authorization: \"Bearer \" + sessionToken, \"Content-Type\": \"application/json\" };\n    }\n\n    async function api(path, opt = {}) {\n      const r = await fetch(path, { ...opt, headers: { ...authHeaders(), ...opt.headers } });\n      if (r.status === 401) {\n        localStorage.removeItem(LS);\n        sessionToken = \"\";\n        location.reload();\n        throw new Error(\"unauthorized\");\n      }\n      const j = await r.json().catch(() => ({}));\n      if (!r.ok) throw new Error(j.message || r.statusText);\n      return j;\n    }\n\n    function audienceOrigin() {\n      return (publicBaseUrl && publicBaseUrl.length > 0 ? publicBaseUrl : location.origin).replace(/\\/+$/, \"\");\n    }\n\n    function injectModeUrl() {\n      return audienceOrigin() + \"/g\";\n    }\n\n    function renderInjectModeUrl() {\n      const input = document.getElementById(\"injectModeUrl\");\n      if (input) input.value = injectModeUrl();\n    }\n\n    async function copyTextFromInput(input) {\n      const value = input.value;\n      if (navigator.clipboard && window.isSecureContext) {\n        await navigator.clipboard.writeText(value);\n      } else {\n        input.focus();\n        input.select();\n        document.execCommand(\"copy\");\n      }\n    }\n\n    function setSettingsFabVisible(on) {\n      const b = document.getElementById(\"btnOpenSettings\");\n      if (!b) return;\n      b.classList.toggle(\"settingsFab--visible\", !!on);\n    }\n\n    function isSettingsDrawerOpen() {\n      return document.getElementById(\"settingsDrawer\").classList.contains(\"settingsDrawer--open\");\n    }\n\n    function openSettingsDrawer() {\n      document.getElementById(\"settingsBackdrop\").classList.add(\"settingsBackdrop--open\");\n      document.getElementById(\"settingsDrawer\").classList.add(\"settingsDrawer--open\");\n      document.getElementById(\"btnOpenSettings\").setAttribute(\"aria-expanded\", \"true\");\n      document.getElementById(\"settingsBackdrop\").setAttribute(\"aria-hidden\", \"false\");\n      renderAdminCodePanel();\n      renderSettingsSummaries();\n    }\n\n    function closeSettingsDrawer() {\n      document.getElementById(\"settingsBackdrop\").classList.remove(\"settingsBackdrop--open\");\n      document.getElementById(\"settingsDrawer\").classList.remove(\"settingsDrawer--open\");\n      document.getElementById(\"btnOpenSettings\").setAttribute(\"aria-expanded\", \"false\");\n      document.getElementById(\"settingsBackdrop\").setAttribute(\"aria-hidden\", \"true\");\n    }\n\n    function isAdminActor() {\n      return actor && actor.role === \"admin\";\n    }\n\n    function renderAdminCodePanel() {\n      const panel = document.getElementById(\"adminCodePanel\");\n      panel.style.display = isAdminActor() ? \"block\" : \"none\";\n    }\n\n    function renderSettingsSummaries() {\n      const total = state && state.ticketCount != null ? state.ticketCount : 0;\n      document.getElementById(\"ticketStatus\").textContent = \"登録中の名刺用URL: \" + total + \" 本\";\n      const undoMeta = document.getElementById(\"undoStateMeta\");\n      if (undoMeta) undoMeta.textContent = state && state.undoAvailable ? \"直前の設定へ戻せます。\" : \"いま戻せる設定はありません。\";\n      const undoBtn = document.getElementById(\"btnUndoState\");\n      if (undoBtn) undoBtn.disabled = !(state && state.undoAvailable);\n    }\n\n    async function loadActiveTicketUrlsIntoDrawer() {\n      const ta = document.getElementById(\"settingsUrlList\");\n      const meta = document.getElementById(\"settingsUrlMeta\");\n      meta.textContent = \"読み込み中…\";\n      ta.value = \"\";\n      try {\n        const d = await api(\"/api/tickets\");\n        const base = audienceOrigin();\n        const total = d.ticketCount != null ? d.ticketCount : 0;\n        const listed = d.listCount != null ? d.listCount : (d.paths || []).length;\n        meta.textContent = \"全登録 \" + total + \" 本 / 未固定 \" + listed + \" 本\";\n        ta.value = (d.paths || []).map((p) => base + p).join(\"\\n\");\n      } catch (e) {\n        meta.textContent = \"\";\n        toast(String(e.message || e));\n      }\n    }\n\n    async function loadAdminCodesIntoDrawer() {\n      if (!isAdminActor()) return;\n      const meta = document.getElementById(\"adminCodeMeta\");\n      const ta = document.getElementById(\"adminCodeList\");\n      meta.textContent = \"読み込み中…\";\n      ta.value = \"\";\n      try {\n        const d = await api(\"/api/admin/codes\");\n        const rows = Array.isArray(d.codes) ? d.codes : [];\n        meta.textContent = \"総ID数 \" + rows.length;\n        ta.value = rows\n          .slice()\n          .reverse()\n          .map((r) => `${r.id}  ${r.role === \"admin\" ? \"管理者\" : \"ユーザー\"}  ${r.active ? \"有効\" : \"停止\"}`)\n          .join(\"\\n\");\n      } catch (e) {\n        meta.textContent = \"\";\n        toast(String(e.message || e));\n      }\n    }\n\n    async function issueCodesBulk() {\n      const n = parseInt(document.getElementById(\"adminIssueCount\").value, 10);\n      if (!Number.isFinite(n) || n < 1 || n > 5000) return toast(\"発行数は1〜5000\");\n      try {\n        const d = await api(\"/api/admin/codes/bulk\", { method: \"POST\", body: JSON.stringify({ count: n }) });\n        const ids = Array.isArray(d.ids) ? d.ids : [];\n        toast(ids.length + \"件発行しました\");\n        const ta = document.getElementById(\"adminCodeList\");\n        ta.value = ids.join(\"\\n\") + (ta.value ? \"\\n\" + ta.value : \"\");\n        loadAdminCodesIntoDrawer();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    async function revokeCodeById() {\n      const id = String(document.getElementById(\"adminRevokeCode\").value || \"\").trim();\n      if (!/^\\d{8}$/.test(id)) return toast(\"8桁IDを入力してください\");\n      if (!confirm(id + \" を停止します。よろしいですか？\")) return;\n      try {\n        await api(\"/api/admin/codes/revoke\", { method: \"POST\", body: JSON.stringify({ id }) });\n        toast(\"停止しました\");\n        document.getElementById(\"adminRevokeCode\").value = \"\";\n        loadAdminCodesIntoDrawer();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    function fmtDateTime(s) {\n      if (!s) return \"—\";\n      const d = new Date(s);\n      if (Number.isNaN(d.getTime())) return s;\n      return d.toLocaleString(\"ja-JP\");\n    }\n\n    async function loadTicketHistoryIntoDrawer() {\n      const meta = document.getElementById(\"settingsHistoryMeta\");\n      const sumTa = document.getElementById(\"settingsHistoryList\");\n      const evTa = document.getElementById(\"settingsRecentEvents\");\n      meta.textContent = \"読み込み中…\";\n      sumTa.value = \"\";\n      evTa.value = \"\";\n      try {\n        const d = await api(\"/api/tickets/history\");\n        meta.textContent = \"URL \" + (d.ticketCount != null ? d.ticketCount : 0) + \" 本 / 合計読取 \" + (d.totalHits != null ? d.totalHits : 0) + \" 回\";\n        const rows = Array.isArray(d.tickets) ? d.tickets : [];\n        sumTa.value = rows\n          .map((r) => {\n            const latest = r.lastHitAt ? fmtDateTime(r.lastHitAt) : \"未読取\";\n            return `${r.path}  |  ${r.hitCount} 回  |  最終: ${latest}`;\n          })\n          .join(\"\\n\");\n        const evs = Array.isArray(d.recentEvents) ? d.recentEvents : [];\n        evTa.value = evs\n          .map((e) => `${fmtDateTime(e.at)}  ${e.path}  query=${e.query || \"-\"}`)\n          .join(\"\\n\");\n      } catch (e) {\n        meta.textContent = \"\";\n        toast(String(e.message || e));\n      }\n    }\n\n    async function downloadTicketQrsZip() {\n      try {\n        const r = await fetch(\"/api/tickets/qr-zip\", { headers: authHeaders() });\n        if (!r.ok) {\n          const j = await r.json().catch(() => ({}));\n          throw new Error(j.message || r.statusText || \"download failed\");\n        }\n        const blob = await r.blob();\n        const a = document.createElement(\"a\");\n        const cd = r.headers.get(\"content-disposition\") || \"\";\n        const m = cd.match(/filename=\\\"?([^\\\";]+)\\\"?/i);\n        a.href = URL.createObjectURL(blob);\n        a.download = (m && m[1]) || \"qr-tickets.zip\";\n        document.body.appendChild(a);\n        a.click();\n        a.remove();\n        setTimeout(() => URL.revokeObjectURL(a.href), 1000);\n        toast(\"ZIPをダウンロードしました\");\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    function buildUrl(template, query) {\n      const host = audienceOrigin();\n      return template.replaceAll(\"{host}\", host).replaceAll(\"{query}\", encodeURIComponent(query));\n    }\n\n    function ensurePresets() {\n      if (!state.templatePresets || !state.templatePresets.length) {\n        const t = state.serviceTemplate || \"https://www.google.com/search?q={query}\";\n        state.templatePresets = [{ label: \"Google\", template: t }];\n        state.activeTemplateIndex = 0;\n      }\n    }\n\n    function ticketKeywordMode() {\n      return state && state.ticketKeywordMode === \"recycle\" ? \"recycle\" : \"frozen\";\n    }\n\n    function qrStateLabel(row) {\n      if (row && row.queryBound) return \"固定済み\";\n      if (row && Number(row.hitCount || 0) > 0) return \"読取済み\";\n      return \"未使用\";\n    }\n\n    function renderQrState() {\n      const summary = document.getElementById(\"qrStateSummary\");\n      const list = document.getElementById(\"qrStateList\");\n      if (!summary || !list) return;\n      const rows = Array.isArray(qrStateRows) ? qrStateRows : [];\n      const fixed = rows.filter((r) => r.queryBound).length;\n      const hit = rows.filter((r) => Number(r.hitCount || 0) > 0).length;\n      summary.textContent = rows.length + \" 本 / 読取済み \" + hit + \" / 固定済み \" + fixed;\n      list.innerHTML = \"\";\n      rows.slice(0, 80).forEach((r) => {\n        const label = qrStateLabel(r);\n        const row = document.createElement(\"div\");\n        row.className = \"qrStateRow\";\n        const badgeClass = r.queryBound ? \"badge badge--fixed\" : Number(r.hitCount || 0) > 0 ? \"badge badge--hit\" : \"badge\";\n        const top = document.createElement(\"div\");\n        top.className = \"qrStateTop\";\n        const pathEl = document.createElement(\"strong\");\n        pathEl.textContent = r.path || \"-\";\n        const badge = document.createElement(\"span\");\n        badge.className = badgeClass;\n        badge.textContent = label;\n        const meta = document.createElement(\"div\");\n        meta.className = \"muted\";\n        meta.textContent = \"読取 \" + Number(r.hitCount || 0) + \" 回 / 最終 \" + fmtDateTime(r.lastHitAt) + \" / \" + (r.query || \"-\");\n        top.appendChild(pathEl);\n        top.appendChild(badge);\n        row.appendChild(top);\n        row.appendChild(meta);\n        list.appendChild(row);\n      });\n      if (!rows.length) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"muted\";\n        empty.textContent = \"QRはまだありません\";\n        list.appendChild(empty);\n      }\n    }\n\n    async function refreshQrState() {\n      try {\n        const d = await api(\"/api/tickets/history\");\n        qrStateRows = Array.isArray(d.tickets) ? d.tickets : [];\n        renderQrState();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    function renderTicketModeUi() {\n      const m = ticketKeywordMode();\n      document.getElementById(\"btnModeRecycle\").className = m === \"recycle\" ? \"btn-primary\" : \"btn-secondary\";\n      document.getElementById(\"btnModeFrozen\").className = m === \"frozen\" ? \"btn-danger\" : \"btn-secondary\";\n      document.getElementById(\"modeLine\").textContent =\n        m === \"frozen\"\n          ? \"いまのモード: 永久化\"\n          : \"いまのモード: リサイクル\";\n    }\n\n    function presetsFromState() {\n      ensurePresets();\n      return (state.templatePresets || []).map((p) => ({\n        label: String(p.label || \"\").trim().slice(0, 60) || \"プリセット\",\n        template: String(p.template || \"\").trim(),\n      }));\n    }\n\n    function renderTemplateBlock() {\n      ensurePresets();\n      const sel = document.getElementById(\"templateSelect\");\n      sel.innerHTML = \"\";\n      (state.templatePresets || []).forEach((p, i) => {\n        const o = document.createElement(\"option\");\n        o.value = String(i);\n        o.textContent = (p.label || `プリセット ${i + 1}`).slice(0, 60);\n        sel.appendChild(o);\n      });\n      const idx = Math.min(\n        Math.max(0, parseInt(state.activeTemplateIndex, 10) || 0),\n        Math.max(0, state.templatePresets.length - 1)\n      );\n      sel.value = String(idx);\n    }\n\n    function syncKeywordFromState(opts = {}) {\n      if (opts && opts.clear) {\n        document.getElementById(\"keyword\").value = \"\";\n        return;\n      }\n      const q = (state.queries && state.queries[0]) || \"\";\n      document.getElementById(\"keyword\").value = q;\n    }\n\n    function renderAll(opts = {}) {\n      ensurePresets();\n      renderTemplateBlock();\n      renderInjectModeUrl();\n      syncKeywordFromState({ clear: !!opts.clearKeyword });\n      renderTicketModeUi();\n      renderSettingsSummaries();\n    }\n\n    async function load() {\n      const data = await api(\"/api/state\");\n      publicBaseUrl = typeof data.publicBaseUrl === \"string\" ? data.publicBaseUrl.trim() : \"\";\n      actor = data.actor || null;\n      state = data.state;\n      renderAll();\n    }\n\n    async function putState(body) {\n      const data = await api(\"/api/state\", { method: \"PUT\", body: JSON.stringify(body) });\n      state = data.state;\n      return data;\n    }\n\n    async function saveKeywordAndTemplateSelection(extra) {\n      const kw = document.getElementById(\"keyword\").value.trim();\n      const presets = presetsFromState();\n      if (!presets.length) return toast(\"プリセットがありません\");\n      for (let i = 0; i < presets.length; i++) {\n        if (!presets[i].template.includes(\"{query}\")) {\n          return toast(\"プリセット \" + (i + 1) + \" に {query} を含めてください\");\n        }\n      }\n      const payloadExtra = extra && typeof extra === \"object\" ? extra : {};\n      await putState({\n        queries: [kw],\n        templatePresets: presets,\n        activeTemplateIndex:\n          extra && extra.activeTemplateIndex !== undefined\n            ? extra.activeTemplateIndex\n            : parseInt(document.getElementById(\"templateSelect\").value, 10) || 0,\n        ticketKeywordMode: ticketKeywordMode(),\n        commitQuery: true,\n        ...payloadExtra,\n      });\n    }\n\n    async function save() {\n      try {\n        await saveKeywordAndTemplateSelection();\n        toast(\"送信しました\");\n        renderAll();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    async function undoState() {\n      try {\n        const data = await api(\"/api/state/undo\", { method: \"POST\", body: JSON.stringify({}) });\n        state = data.state;\n        toast(\"ひとつ戻しました\");\n        renderAll();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n\n    document.getElementById(\"templateSelect\").addEventListener(\"change\", async (e) => {\n      const idx = parseInt(e.target.value, 10);\n      if (!Number.isFinite(idx) || !state) return;\n      const kw = document.getElementById(\"keyword\").value.trim();\n      try {\n        const presets = presetsFromState();\n        if (!presets.every((p) => p.template.includes(\"{query}\"))) {\n          toast(\"各プリセットに {query} が必要です\");\n          renderAll();\n          document.getElementById(\"keyword\").value = kw;\n          return;\n        }\n        await putState({\n          templatePresets: presets,\n          activeTemplateIndex: idx,\n          ticketKeywordMode: ticketKeywordMode(),\n          commitQuery: false,\n        });\n        toast(\"切り替えました\");\n        renderAll();\n        document.getElementById(\"keyword\").value = kw;\n      } catch (err) {\n        toast(String(err.message || err));\n        renderAll();\n        document.getElementById(\"keyword\").value = kw;\n      }\n    });\n\n    document.getElementById(\"btnPreviewKeyword\").onclick = () => {\n      ensurePresets();\n      const idx = parseInt(document.getElementById(\"templateSelect\").value, 10) || 0;\n      const tmpl = (state.templatePresets[idx] && state.templatePresets[idx].template) || \"\";\n      const kw = document.getElementById(\"keyword\").value.trim();\n      if (!tmpl.includes(\"{query}\")) return toast(\"{query} を含めてください\");\n      if (!kw) return toast(\"キーワードが空です\");\n      window.open(buildUrl(tmpl, kw), \"_blank\");\n    };\n\n    document.getElementById(\"btnOpenSettings\").onclick = () => {\n      if (!isSettingsDrawerOpen()) openSettingsDrawer();\n      else closeSettingsDrawer();\n    };\n    document.getElementById(\"btnCloseSettings\").onclick = () => closeSettingsDrawer();\n    document.getElementById(\"settingsBackdrop\").onclick = () => closeSettingsDrawer();\n    document.getElementById(\"btnRefreshUrlList\").onclick = () => loadActiveTicketUrlsIntoDrawer();\n    document.getElementById(\"btnRefreshHistory\").onclick = () => loadTicketHistoryIntoDrawer();\n    document.getElementById(\"btnDownloadQrZip\").onclick = () => downloadTicketQrsZip();\n    document.getElementById(\"btnAdminIssueCodes\").onclick = () => issueCodesBulk();\n    document.getElementById(\"btnAdminRefreshCodes\").onclick = () => loadAdminCodesIntoDrawer();\n    document.getElementById(\"btnAdminRevokeCode\").onclick = () => revokeCodeById();\n    document.getElementById(\"btnUndoState\").onclick = () => undoState();\n    document.getElementById(\"btnRefreshQrState\").onclick = () => refreshQrState();\n\n    document.getElementById(\"settingsUrlSection\").addEventListener(\"toggle\", (e) => {\n      if (e.target.open) loadActiveTicketUrlsIntoDrawer();\n    });\n    document.getElementById(\"settingsHistorySection\").addEventListener(\"toggle\", (e) => {\n      if (e.target.open) loadTicketHistoryIntoDrawer();\n    });\n    document.getElementById(\"settingsQrStateSection\").addEventListener(\"toggle\", (e) => {\n      if (e.target.open) refreshQrState();\n    });\n    document.getElementById(\"adminCodePanel\").addEventListener(\"toggle\", (e) => {\n      if (e.target.open) loadAdminCodesIntoDrawer();\n    });\n\n    document.addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Escape\" && isSettingsDrawerOpen()) closeSettingsDrawer();\n    });\n\n    document.getElementById(\"gateBtn\").onclick = async () => {\n      const id = document.getElementById(\"gateToken\").value.trim();\n      if (!/^\\d{8}$/.test(id)) return toast(\"8桁のログインIDを入力してください\");\n      try {\n        const d = await fetch(\"/api/login\", {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ id }),\n        }).then((r) => r.json());\n        if (!d.ok || !d.token) {\n          return toast(d.message || \"ログインに失敗しました\");\n        }\n        sessionToken = d.token;\n        localStorage.setItem(LS, sessionToken);\n        startApp();\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    };\n\n    document.getElementById(\"saveBtn\").onclick = () => save();\n    document.getElementById(\"btnCopyInjectUrl\").onclick = async () => {\n      try {\n        await copyTextFromInput(document.getElementById(\"injectModeUrl\"));\n        toast(\"コピーしました\");\n      } catch (e) {\n        toast(\"コピーできませんでした\");\n      }\n    };\n\n    async function setTicketKeywordMode(mode) {\n      try {\n        const data = await api(\"/api/state\", {\n          method: \"PUT\",\n          body: JSON.stringify({ ticketKeywordMode: mode }),\n        });\n        state = data.state;\n        document.getElementById(\"keyword\").value = \"\";\n        toast(mode === \"frozen\" ? \"永久化にしました\" : \"リサイクルにしました\");\n        renderAll({ clearKeyword: true });\n      } catch (e) {\n        toast(String(e.message || e));\n      }\n    }\n    document.getElementById(\"btnModeFrozen\").onclick = () => setTicketKeywordMode(\"frozen\");\n    document.getElementById(\"btnModeRecycle\").onclick = () => setTicketKeywordMode(\"recycle\");\n\n    document.getElementById(\"btnIssueTickets\").onclick = () => {\n      const n = parseInt(document.getElementById(\"ticketCount\").value, 10);\n      if (!Number.isFinite(n) || n < 1 || n > 5000) return toast(\"枚数は1〜5000\");\n      api(\"/api/tickets/bulk\", { method: \"POST\", body: JSON.stringify({ count: n }) })\n        .then((d) => {\n          state.ticketCount = d.ticketCount;\n          const base = audienceOrigin();\n          const lines = (d.tickets || []).map((x) => base + x.path);\n          document.getElementById(\"ticketUrls\").value = lines.join(\"\\n\");\n          toast(\"発行しました\");\n          renderAll();\n          if (document.getElementById(\"settingsQrStateSection\").open) refreshQrState();\n        })\n        .catch((e) => toast(String(e.message || e)));\n    };\n    document.getElementById(\"btnClearTickets\").onclick = () => {\n      if (!confirm(\"名刺用URLをすべて削除します。よろしいですか？\")) return;\n      api(\"/api/tickets/clear\", { method: \"POST\", body: JSON.stringify({ confirm: true }) })\n        .then((d) => {\n          state.ticketCount = d.ticketCount;\n          document.getElementById(\"ticketUrls\").value = \"\";\n          toast(\"削除しました\");\n          renderAll();\n          if (document.getElementById(\"settingsQrStateSection\").open) refreshQrState();\n        })\n        .catch((e) => toast(String(e.message || e)));\n    };\n\n    let pollTimer = null;\n    function startPublicUrlPoller() {\n      if (pollTimer) return;\n      let n = 0;\n      pollTimer = setInterval(async () => {\n        n++;\n        if (n > 45) {\n          clearInterval(pollTimer);\n          pollTimer = null;\n        }\n        try {\n          const r = await fetch(\"/api/public-qr-hint\");\n          const d = await r.json();\n          const base = (d.publicBaseUrl || \"\").replace(/\\/+$/, \"\");\n          if (base && state) {\n            const changed = base !== publicBaseUrl;\n            publicBaseUrl = base;\n            if (changed) renderAll();\n          }\n        } catch (_) {}\n      }, 2000);\n    }\n\n    async function startApp() {\n      try {\n        await load();\n        gate.style.display = \"none\";\n        appEl.style.display = \"block\";\n        setSettingsFabVisible(true);\n        renderAll({ clearKeyword: true });\n        startPublicUrlPoller();\n      } catch (e) {\n        localStorage.removeItem(LS);\n        sessionToken = \"\";\n        actor = null;\n        gate.style.display = \"block\";\n        appEl.style.display = \"none\";\n        setSettingsFabVisible(false);\n        closeSettingsDrawer();\n        toast(\"読み込み失敗: IDを確認してください\");\n      }\n    }\n\n    renderInjectModeUrl();\n    if (sessionToken) startApp();\n\n    (function loadAppVersion() {\n      fetch(\"/api/version\")\n        .then((r) => r.json())\n        .then((d) => {\n          const el = document.getElementById(\"appVersionBar\");\n          if (el && d.version) el.textContent = \"バージョン \" + d.version;\n        })\n        .catch(() => {\n          const el = document.getElementById(\"appVersionBar\");\n          if (el) el.textContent = \"\";\n        });\n    })();\n  </script>\n</body>\n</html>\n";
